public partial class AbilityUtils
{
	public static T GetLevelValue<T>(T[]? array, int level, T defaultValueIfNotFound)
	{
		if (array == null || array.Length == 0)
		{
			return defaultValueIfNotFound;
		}
		if (level >= 1 && level - 1 < array.Length)
		{
			return array[level - 1];
		}
		if (level == 0)
		{
			return array[0];
		}
		return array[^1];
	}
	public static float GetAttrValue(IAttributeSet? attrSet, EAttributeType attrId, EAttributeBasedFloatCalculationType attrCalcPolicy)
	{
		if (attrSet == null)
		{
			return 0f;
		}
		return attrCalcPolicy switch
		{
			EAttributeBasedFloatCalculationType.BonusValue => attrSet.GetCurrentValue(attrId) - attrSet.GetBaseValue(attrId), 
			EAttributeBasedFloatCalculationType.CurrentValue => attrSet.GetCurrentValue(attrId), 
			_ => attrSet.GetBaseValue(attrId), 
		};
	}
